SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, compound_structures.canonical_smiles, 'EFO:' || drug_indication.efo_id AS indication_curie, drug_indication.mesh_heading AS indication_label, drug_indication.max_phase_for_ind FROM molecule_dictionary INNER JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno INNER JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE drug_indication.max_phase_for_ind = 4 AND LOWER(drug_indication.mesh_heading) = 'chronic kidney disease' ORDER BY molecule_dictionary.chembl_id ASC, molecule_dictionary.pref_name ASC, compound_structures.canonical_smiles ASC, indication_curie ASC, indication_label ASC, drug_indication.max_phase_for_ind ASC
